function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1800, 2000) : int(1, 9);
  const top = size === 'large' ? 100000 : (rand() < 0.7 ? 4 : 100000);
  const shape = rand();
  let nums = Array.from({ length: n }, () => int(0, top));
  if (shape < 0.15) nums.sort((a, b) => a - b);
  else if (shape < 0.3) nums.sort((a, b) => b - a);
  else if (shape < 0.4) nums = nums.map(() => nums[0]);
  else if (shape < 0.55) nums = nums.map((_, i) => (i % 7) * Math.floor(top / 7) + int(0, 1));
  return [nums];
}
